#!/usr/bin/env node
// Historical backtest of dkvand's OWN bathing-site bacterial risk formula
// against real PULS lab samples — the actual validation this project set
// out to do ("validate against scores generated by historic water tests
// and weather data"). scripts/validate-predictions.js instead compared
// against badevand_daily_risk, a LIVE accumulator table that only started
// recording ~5 weeks before this script was written — it can never use
// the 30+ years of real lab history badevand-proeve-historik.json has.
// This script fixes that by RECOMPUTING the model's own formula, per
// historical sample date, from real historical rainfall — same approach
// as ukwater's scripts/validate-predictions.js (outlet-level, recomputed
// from Open-Meteo archive data), extended to dkvand's more elaborate
// site-level cascade.
//
// How a badested's score is recomputed for a past date:
//   1. Every PULS outlet's OWN bacterial risk (risk-model.js's
//      computeRisk()) is recomputed from real historical hourly rainfall
//      (Open-Meteo archive API), fetched per weather GRID CELL (risk-
//      model.js's cellKey(), 0.25°) — not per outlet — since many outlets
//      share a cell, exactly like the live app's weatherCache. Each
//      cell's FULL hourly series over the whole validation window is
//      fetched ONCE, then sliced locally per sample date — turns what
//      would be (cells × dates) archive calls into just (cells) calls.
//   2. antecedentMM / lastEventAge are reconstructed with the exact same
//      formulas server.js's computeMetrics()/estimateLastEventAge() use
//      live (τ=3-day decay, upward-threshold-crossing detection) — both
//      are already pure functions of a chronological hourly rainfall
//      array, nothing here is approximated.
//   3. The scored outlets are fed into badevand-risk.js's REAL
//      computeBadevandRiskCascade() — the same geometry/outlet-matching
//      code the live app runs — to get each badested's aggregate bact
//      score, exactly as production does.
//
// One remaining, documented deviation from the live formula:
//   - seasonalTau()/seasonalTauViral() read the CURRENT real-world month
//     internally (no override hook) — this script reimplements their
//     exact formula (using risk-model.js's own exported DK_WATER_TEMP/
//     DK_DAYLIGHT_HRS/Q10/TAU_BASE_DAYS constants) parameterized by the
//     historical sample's month instead, so seasonal decay reflects the
//     actual season being backtested, not today's.
//
// Restricted to a RECENT window (WINDOW_DAYS below), not the full 30+
// year sample history: puls-data.json reflects TODAY's outlet locations/
// thresholds, not historical sewer infrastructure — scoring a 1995
// sample against 2026 outlet data would not be a meaningful test. This
// also keeps the Open-Meteo archive call count tractable (one call per
// distinct grid cell covering Denmark, not per cell per date).
//
// NYT (bruger-krav 2026-09-05 — "we have no current information, so only
// downstream locations should show elevated coli"): getCurrentAt is no
// longer unconditionally null. scripts/fetch_currents_historical.py
// fetches real historical CMEMS current direction per weather-grid cell
// (same "once per cell, sliced per date" pattern as the rainfall archive
// above) — but CMEMS' reanalysis products only cover up to ~1-1.5 years
// before today (see that script's filehead), so this run FURTHER narrows
// the sample comparison window to whatever date range actually came back
// with current data for every cell (see earliestCommonDate below) —
// smaller sample count than the full WINDOW_DAYS, but every compared
// sample now gets a real, direction-aware downstream check instead of the
// isotropic (distance-only) fallback. A cell with no current data for a
// given date still falls back to isotropic for just that lookup, same
// fallback path computeBadevandRiskCascade() already takes live.
//
// Manual/occasional, not a live server code path. No DATABASE_URL needed
// — everything here is badevand-proeve-historik.json, puls-data.json, the
// static geometry files computeBadevandRiskCascade() already reads, live
// Open-Meteo archive calls, and live CMEMS reanalysis subset() calls
// (requires CMEMS_USERNAME/CMEMS_PASSWORD — same Fly secrets fetch_currents.py
// uses live, see fetch_currents_historical.py's filehead for the currently
// UNVERIFIED dataset_id's it assumes).
'use strict';

const fs = require('fs');
const path = require('path');
const { execFile } = require('child_process');
const riskModel = require('../risk-model');
const badevandRisk = require('../badevand-risk');

const STATIC_DIR = path.join(__dirname, '..');
const SAMPLES_FILE = path.join(STATIC_DIR, 'badevand-proeve-historik.json');
const PULS_DATA_FILE = path.join(STATIC_DIR, 'puls-data.json');

const ECOLI_THRESHOLD = 500;
const ENTERO_THRESHOLD = 200;
const FLAG_THRESHOLD = 0.2; // same 'medium' cutoff used throughout this codebase
const WINDOW_DAYS = 730; // ~2 years back from the latest sample — see filehead
const HOURLY_WEEK_HOURS = 7 * 24;
const BUFFER_DAYS = 8; // fetched before window start so the earliest date still gets a full 7-day lookback
const CELL_CONCURRENCY = 4;

function isoDate(d) { return d.toISOString().slice(0, 10); }
function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, ms)); }

function sampleFailed(sample) {
  const { ecoli, enterokokker } = sample;
  if (ecoli == null && enterokokker == null) return null;
  return (ecoli != null && ecoli >= ECOLI_THRESHOLD) || (enterokokker != null && enterokokker >= ENTERO_THRESHOLD);
}

// Exact formula from risk-model.js's seasonalTau()/seasonalTauViral(),
// parameterized by month instead of reading new Date().getMonth() — uses
// that module's own exported constants, not re-guessed numbers.
function seasonalTauForMonth(month) {
  const T = riskModel.DK_WATER_TEMP[month];
  const light = riskModel.DK_DAYLIGHT_HRS[month];
  const tempFactor = Math.pow(riskModel.Q10, (20 - T) / 10);
  const lightFactor = 12 / Math.max(light, 4);
  return riskModel.TAU_BASE_DAYS * tempFactor * lightFactor;
}
function seasonalTauViralForMonth(month) {
  const T = riskModel.DK_WATER_TEMP[month];
  const light = riskModel.DK_DAYLIGHT_HRS[month];
  const tempFactor = Math.pow(riskModel.Q10_VIRAL, (20 - T) / 10);
  const lightFactor = T >= 12 ? (12 / Math.max(light, 4)) : 1.0;
  return riskModel.TAU_VIRAL_BASE * tempFactor * lightFactor;
}

// NYT (bruger-krav 2026-09-05 — "kun nedstrøms lokationer bør vise højere
// coli"): historisk strømretning pr. celle, til at erstatte getCurrentAt's
// hidtidige `null` (isotropisk fallback for ALLE kystvande, uanset reel
// strømretning — se computeBadevandRiskCascade()'s egen getCurrentAt-
// kommentar for hvorfor det matcher HVER retning som "muligvis nedstrøms").
// Se scripts/fetch_currents_historical.py's filhoved for datakilde/
// dataset_id-forbehold og hvorfor det er ét kald pr. celle (parallelt med
// fetchArchive() ovenfor), ikke ét fladt gitter.
const PYTHON_BIN = process.env.PYTHON_BIN || 'python3';
const CURRENTS_SCRIPT = path.join(__dirname, 'fetch_currents_historical.py');
const CURRENTS_TIMEOUT_MS = 150 * 1000; // matcher fetch_currents.py's egen HARD_TIMEOUT_SECONDS

function fetchHistoricalCurrentsForCell(lat, lng, startDate) {
  return new Promise((resolve, reject) => {
    const child = execFile(
      PYTHON_BIN, [CURRENTS_SCRIPT],
      { timeout: CURRENTS_TIMEOUT_MS, maxBuffer: 16 * 1024 * 1024 },
      (err, stdout, stderr) => {
        if (stderr && stderr.trim()) console.warn(`  [currents ${lat},${lng}] stderr:`, stderr.trim().slice(0, 300));
        let parsed;
        try { parsed = JSON.parse((stdout || '').trim()); }
        catch (parseErr) { return reject(new Error(`fetch_currents_historical.py gav ugyldig JSON: ${parseErr.message}`)); }
        if (parsed.error) return reject(new Error(parsed.error));
        resolve(parsed);
      },
    );
    child.stdin.write(JSON.stringify({ lat, lng, start: startDate }));
    child.stdin.end();
  });
}

async function fetchArchive(lat, lng, startDate, endDate, attempt = 0) {
  const url = `https://archive-api.open-meteo.com/v1/archive?latitude=${lat}&longitude=${lng}&start_date=${startDate}&end_date=${endDate}&hourly=precipitation&timezone=UTC`;
  const res = await fetch(url);
  if (res.status === 429) {
    if (attempt >= 6) throw new Error(`Open-Meteo archive API 429 for ${lat},${lng} — gave up after ${attempt} retries`);
    await sleep(2000 * 2 ** attempt);
    return fetchArchive(lat, lng, startDate, endDate, attempt + 1);
  }
  if (!res.ok) {
    if (attempt >= 2) throw new Error(`Open-Meteo archive API ${res.status} for ${lat},${lng} — gave up after ${attempt} retries`);
    await sleep(1000 * (attempt + 1));
    return fetchArchive(lat, lng, startDate, endDate, attempt + 1);
  }
  const json = await res.json();
  return { time: json.hourly.time, mm: json.hourly.precipitation };
}

async function mapWithConcurrency(items, limit, fn, pacingMs, onProgress) {
  const results = new Array(items.length);
  let next = 0, done = 0;
  async function worker() {
    while (next < items.length) {
      const i = next++;
      results[i] = await fn(items[i], i).catch((err) => ({ error: err.message }));
      done++;
      if (onProgress) onProgress(done, items.length);
      if (pacingMs) await sleep(pacingMs);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

// Slice a cell's full hourly series to the 7×24 hours ending at `endDate`
// (UTC midday convention, matching this validation's other historical
// scripts) — mirrors server.js computeMetrics()'s hourlyWeek: chronological
// (oldest first), only hours at or before "now".
function hourlyWeekEndingAt(cellSeries, endDate) {
  const endMs = new Date(`${endDate}T12:00:00Z`).getTime();
  const startMs = endMs - HOURLY_WEEK_HOURS * 3600 * 1000;
  const out = [];
  for (let i = 0; i < cellSeries.time.length; i++) {
    const raw = cellSeries.time[i];
    const tMs = new Date(raw.endsWith('Z') ? raw : `${raw}Z`).getTime();
    if (tMs >= startMs && tMs <= endMs) out.push(Math.max(cellSeries.mm[i] || 0, 0));
  }
  return out;
}

async function main() {
  if (!fs.existsSync(SAMPLES_FILE)) {
    console.error(`${SAMPLES_FILE} doesn't exist yet.`);
    console.error('Run scripts/build-badevand-analyseresultater.js against a fresh PULS CSV export first.');
    process.exit(1);
  }
  if (!fs.existsSync(PULS_DATA_FILE)) {
    console.error(`${PULS_DATA_FILE} doesn't exist — needed for outlet locations/thresholds.`);
    process.exit(1);
  }

  const samplesData = JSON.parse(fs.readFileSync(SAMPLES_FILE, 'utf8'));
  const allSamples = samplesData.samples;
  if (allSamples.length === 0) { console.error('No samples in the file.'); process.exit(1); }
  const maxDate = allSamples.reduce((m, s) => (s.dateIso > m ? s.dateIso : m), allSamples[0].dateIso);
  const windowStart = isoDate(new Date(new Date(`${maxDate}T00:00:00Z`).getTime() - WINDOW_DAYS * 86400000));
  const samples = allSamples.filter((s) => s.dateIso >= windowStart);
  console.log(`Loaded ${allSamples.length} samples total.`);
  console.log(`Restricting to ${windowStart}..${maxDate} (today's outlet data isn't valid for older samples): ${samples.length} samples.`);
  if (samples.length === 0) { console.error('Nothing in the recent window — nothing to validate.'); process.exit(1); }

  const pulsRaw = JSON.parse(fs.readFileSync(PULS_DATA_FILE, 'utf8'));
  const rows = pulsRaw.d || pulsRaw;
  const outlets = rows
    .map((row, i) => ({ id: String(i), ...riskModel.derivePulsFields(row), viralScore: null, algaeScore: null, foreRisk: null }))
    .filter((o) => o.lat != null && o.lng != null);
  console.log(`Loaded ${outlets.length} outlets.`);

  const cellOf = new Map();
  for (const o of outlets) {
    const key = riskModel.cellKey(o.lat, o.lng);
    if (!cellOf.has(key)) cellOf.set(key, { lat: o.lat, lng: o.lng });
  }
  console.log(`${cellOf.size} distinct weather grid cells to fetch (one Open-Meteo call each, covering the full window).`);

  const fetchStart = isoDate(new Date(new Date(`${windowStart}T00:00:00Z`).getTime() - BUFFER_DAYS * 86400000));
  const cellEntries = [...cellOf.entries()];
  const cellResults = await mapWithConcurrency(
    cellEntries, CELL_CONCURRENCY,
    async ([key, { lat, lng }]) => ({ key, series: await fetchArchive(lat, lng, fetchStart, maxDate) }),
    300,
    (done, total) => { if (done % 20 === 0 || done === total) console.log(`  ...${done}/${total} cells fetched`); },
  );
  const cellFailures = cellResults.filter((r) => r.error);
  if (cellFailures.length > 0) console.warn(`⚠ ${cellFailures.length}/${cellEntries.length} cells failed to fetch — outlets in those cells get no risk score (treated as no-data, not as zero risk).`);
  const cellSeriesByKey = new Map(cellResults.filter((r) => !r.error).map((r) => [r.key, r.series]));

  // NYT (bruger-krav 2026-09-05 — "kun nedstrøms lokationer bør vise højere
  // coli"): historisk strømretning pr. celle, samme "ét kald pr. celle,
  // hele intervallet i ét hug"-mønster som nedbøren ovenfor. CMEMS'
  // reanalyse-produkter dækker typisk kun til et sted mellem 1-1,5 år før
  // i dag (se fetch_currents_historical.py's filhoved) — den FAKTISKE
  // grænse er derfor kun kendt EFTER dette kald, ikke en konstant her.
  const CURRENTS_CONCURRENCY = 3; // lavere end CELL_CONCURRENCY — CMEMS subset()-kald er tungere end Open-Meteo
  console.log(`\nFetching historical current direction for ${cellEntries.length} cells (this can take a while — one CMEMS subset() call per cell)...`);
  const currentResults = await mapWithConcurrency(
    cellEntries, CURRENTS_CONCURRENCY,
    async ([key, { lat, lng }]) => ({ key, series: await fetchHistoricalCurrentsForCell(lat, lng, fetchStart) }),
    500,
    (done, total) => { if (done % 20 === 0 || done === total) console.log(`  ...${done}/${total} cells' current history fetched`); },
  );
  const currentFailures = currentResults.filter((r) => r.error);
  if (currentFailures.length > 0) console.warn(`⚠ ${currentFailures.length}/${cellEntries.length} cells failed to fetch current data — those cells fall back to isotropic matching, same as before this change.`);

  // Pr.-celle Map<dateIso, {uo, vo}> — O(1) opslag i selve backtest-løkken.
  const currentSeriesByKey = new Map();
  let earliestCommonDate = null; // SENESTE af hver celles EGEN tidligste dato — garanterer alle celler-med-data har fuld dækning fra dette punkt og frem
  for (const r of currentResults) {
    if (r.error || !r.series || r.series.dates.length === 0) continue;
    const byDate = new Map();
    for (let i = 0; i < r.series.dates.length; i++) byDate.set(r.series.dates[i], { uo: r.series.uo[i], vo: r.series.vo[i] });
    currentSeriesByKey.set(r.key, byDate);
    const cellEarliest = r.series.dates[0]; // kronologisk (ældste først), se fetch_currents_historical.py
    if (earliestCommonDate === null || cellEarliest > earliestCommonDate) earliestCommonDate = cellEarliest;
  }
  console.log(`${currentSeriesByKey.size}/${cellEntries.length} celler har historisk strømdata.`);

  // Selve vinduesindsnævringen — ethvert prøvedato ÆLDRE end den fælles
  // reelle CMEMS-dækning droppes helt (IKKE blot isotropisk fallback for
  // dem): formålet er at HVER sammenlignet prøve i den endelige matrix får
  // en reel, retningsbevidst nedstrøms-vurdering, ikke en blanding af to
  // metoder, der ville gøre confusion-matrixen svær at fortolke.
  let windowedSamples = samples;
  if (earliestCommonDate) {
    windowedSamples = samples.filter((s) => s.dateIso >= earliestCommonDate);
    console.log(`Indsnævrer til CMEMS' faktiske dækning: ${earliestCommonDate}..${maxDate} — ${windowedSamples.length}/${samples.length} prøver tilbage.\n`);
  } else {
    console.warn('⚠ Ingen celler fik nogen historisk strømdata — fortsætter med FULD isotropisk fallback (som før denne ændring), ingen prøver droppet. Tjek dataset_id\'erne i fetch_currents_historical.py (se dens filhoved) hvis dette er uventet.\n');
  }

  const samplesByDate = new Map();
  for (const s of windowedSamples) {
    if (!samplesByDate.has(s.dateIso)) samplesByDate.set(s.dateIso, []);
    samplesByDate.get(s.dateIso).push(s);
  }
  const distinctDates = [...samplesByDate.keys()].sort();
  console.log(`${distinctDates.length} distinct sample dates to backtest (one cascade recompute each).\n`);

  let tp = 0, fp = 0, tn = 0, fn = 0, noResult = 0, noPrediction = 0, cascadeErrors = 0;
  let dateIdx = 0;
  for (const dateIso of distinctDates) {
    dateIdx++;
    if (dateIdx % 25 === 0) console.log(`  ...${dateIdx}/${distinctDates.length} dates processed`);

    const month = new Date(`${dateIso}T12:00:00Z`).getUTCMonth();
    const tau = seasonalTauForMonth(month);
    const tauV = seasonalTauViralForMonth(month);

    const points = outlets.map((o) => {
      const series = cellSeriesByKey.get(riskModel.cellKey(o.lat, o.lng));
      if (!series) return { ...o, riskScore: null };
      const hourlyWeek = hourlyWeekEndingAt(series, dateIso);
      const decayedSeries = riskModel.accumulateDecayed(hourlyWeek, 3.0);
      const antecedentMM = decayedSeries.length ? decayedSeries[decayedSeries.length - 1] : 0;
      const lastEventAge = riskModel.estimateLastEventAge(hourlyWeek, o.thresholdMm);
      const { risk } = riskModel.computeRisk({
        overflowProbBase: o.overflowProbBase, meanVolumePerEvent: o.meanVolumePerEvent,
        thresholdMm: o.thresholdMm, precipMM: antecedentMM, lastEventAge,
      });
      return { ...o, riskScore: risk };
    });

    // NYT (bruger-krav 2026-09-05) — reel, dato-specifik strømretning i
    // stedet for den hidtidige `null` (som tvang isotropisk/afstands-kun
    // matching for ALLE kystvande, se computeBadevandRiskCascade()'s egen
    // getCurrentAt-kommentar). null for en celle uden strømdata for netop
    // denne dato er BEVIDST — kalderen falder da selv tilbage til
    // isotropisk for lige dét opslag, ingen særskilt håndtering nødvendig.
    const getCurrentAtForDate = (lat, lng) => currentSeriesByKey.get(riskModel.cellKey(lat, lng))?.get(dateIso) ?? null;

    let result;
    try {
      result = await badevandRisk.computeBadevandRiskCascade(points, () => tau, () => tauV, STATIC_DIR, 200, getCurrentAtForDate);
    } catch (err) {
      cascadeErrors += samplesByDate.get(dateIso).length;
      continue;
    }
    const bactBySite = new Map((result.badevand || []).map((b) => [b.id, b.bact]));

    for (const sample of samplesByDate.get(dateIso)) {
      const failed = sampleFailed(sample);
      if (failed === null) { noResult++; continue; }
      const bact = bactBySite.get(sample.siteId);
      if (bact == null) { noPrediction++; continue; }
      const flagged = bact >= FLAG_THRESHOLD;
      if (failed && flagged) tp++;
      else if (!failed && flagged) fp++;
      else if (!failed && !flagged) tn++;
      else fn++;
    }
  }

  const compared = tp + fp + tn + fn;
  console.log('');
  console.log(`Compared: ${compared} sample+prediction pairs`);
  console.log(`Skipped: ${noResult} (no lab result), ${noPrediction} (site had no cascade result that day)${cascadeErrors > 0 ? `, ${cascadeErrors} (cascade computation failed for that date)` : ''}`);
  console.log('');
  console.log('Confusion matrix (failed sample vs. flagged historical recompute):');
  console.log(`  True positive  (failed + flagged):     ${tp}`);
  console.log(`  False positive (passed + flagged):     ${fp}`);
  console.log(`  True negative  (passed + not flagged): ${tn}`);
  console.log(`  False negative (failed + not flagged): ${fn}`);
  if (compared > 0) {
    const totalFailed = tp + fn;
    const totalPassed = fp + tn;
    console.log('');
    if (totalFailed > 0) console.log(`  Recall (caught real fails):  ${((tp / totalFailed) * 100).toFixed(1)}% (${tp}/${totalFailed})`);
    if (totalPassed > 0) console.log(`  False alarm rate:            ${((fp / totalPassed) * 100).toFixed(1)}% (${fp}/${totalPassed})`);
    console.log(`  Overall accuracy:            ${(((tp + tn) / compared) * 100).toFixed(1)}%`);
  }
}

main().catch((err) => {
  console.error('validate-predictions-historical failed:', err);
  process.exit(1);
});
